class LocalCapture extends AudioWorkletProcessor{constructor(){super();this.pending=new Float32Array(4096);this.used=0;this.remaining=0;this.active=false;this.port.onmessage=e=>{if(e.data.type==='start'){this.used=0;this.remaining=e.data.samples;this.active=true;}if(e.data.type==='stop')this.finish();};}flush(){if(this.used){this.port.postMessage({type:'chunk',samples:this.pending.slice(0,this.used)},[]);this.used=0;}}finish(){if(!this.active)return;this.flush();this.active=false;this.port.postMessage({type:'done'});}process(inputs,outputs){const data=inputs[0]?.[0];if(data&&this.active){let at=0;while(at<data.length&&this.remaining>0){const len=Math.min(data.length-at,4096-this.used,this.remaining);this.pending.set(data.subarray(at,at+len),this.used);this.used+=len;this.remaining-=len;at+=len;if(this.used===4096)this.flush();}if(this.remaining<=0)this.finish();}for(const output of outputs)for(const channel of output)channel.fill(0);return true;}}registerProcessor('local-capture',LocalCapture);
